import{_ as t}from"./chunks/emo.CGwrrK0y.js";import{_ as o}from"./chunks/emergency-button-gui.DfAcsUhG.js";import{_ as a,o as r,c as n,a5 as i}from"./chunks/framework.CcrBcQWS.js";const b=JSON.parse('{"title":"6-3. Emergency Stop & Recovery","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/common/emo.md","filePath":"guides/common/emo.md","lastUpdated":1787021357000}'),s={name:"guides/common/emo.md"};function l(c,e,p,m,h,d){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="_6-3-emergency-stop-recovery" tabindex="-1">6-3. Emergency Stop &amp; Recovery <a class="header-anchor" href="#_6-3-emergency-stop-recovery" aria-label="Permalink to &quot;6-3. Emergency Stop &amp; Recovery&quot;">​</a></h1><p><strong>Goal:</strong> Know how to stop the robot immediately in an emergency and how to safely resume operation.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>Always keep the emergency stop button accessible during operation. In any situation where the robot poses a risk to people or property, press the emergency stop button immediately.</p></div></div><h2 id="physical-emergency-stop-button" tabindex="-1">Physical Emergency Stop Button <a class="header-anchor" href="#physical-emergency-stop-button" aria-label="Permalink to &quot;Physical Emergency Stop Button&quot;">​</a></h2><figure><img src="'+t+'" alt="Emergency stop button on the rear of the robot"><figcaption style="text-align:center;">[ Emergency stop push button — located on the rear of the robot ]</figcaption></figure><p>When the <strong>emergency stop button</strong> is pressed:</p><ul><li>All joints switch to <strong>High Damping</strong> mode.</li><li>The robot resists external motion but does <strong>not</strong> accept torque or position commands.</li><li>The robot may lose its posture and settle to the ground under gravity.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>High Damping mode protects both the user and the robot. The robot will not execute any motion commands until the emergency stop is cleared and the robot is re-initialized.</p></div></div><h2 id="gui-emergency-stop" tabindex="-1">GUI Emergency Stop <a class="header-anchor" href="#gui-emergency-stop" aria-label="Permalink to &quot;GUI Emergency Stop&quot;">​</a></h2><p>You can also trigger an emergency stop from RBQGUI without reaching the physical button.</p><figure><img src="'+o+'" alt="Emergency stop button in RBQGUI"><figcaption style="text-align:center;">[ EMERGENCY button in RBQGUI top bar ]</figcaption></figure><p>Pressing the <strong>EMERGENCY</strong> button in the top bar of RBQGUI has the same effect as the physical button — all joints enter High Damping mode immediately.</p><h2 id="recovery-procedure" tabindex="-1">Recovery Procedure <a class="header-anchor" href="#recovery-procedure" aria-label="Permalink to &quot;Recovery Procedure&quot;">​</a></h2><p>After an emergency stop, follow these steps to safely resume operation:</p><ol><li><strong>Ensure safety</strong> — Confirm that all people and animals have moved at least 2 m away from the robot.</li><li><strong>Release the button</strong> — Rotate the physical emergency stop button clockwise to return it to its original (unlocked) position.</li><li><strong>Return to initial pose</strong> — If the robot has fallen or shifted, manually return it to the <a href="/RBQ/nightly/guides/common/initial-pose.html">correct initial pose</a> on a flat surface.</li><li><strong>Re-initialize</strong> — Press the <strong>Stance</strong> button in RBQGUI, or run <strong>Auto Start</strong> from the <a href="/RBQ/nightly/guides/common/controller-wifi-connect.html#auto-start">Controller &amp; Wi-Fi</a> setup.</li><li><strong>Verify</strong> — Confirm that the EMERGENCY indicator is no longer lit and that all Auto Start items are green before resuming operation.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Do not attempt to force-move the joints while the robot is in High Damping mode. Return the robot to the initial pose carefully and only after the emergency stop has been released.</p></div></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/manual/safety/general-safety-warning-precautions.html">General Safety Guidelines</a></li><li><a href="/RBQ/nightly/manual/safety/emergency-stop-procedures.html">Emergency Stop Procedures (detailed)</a></li><li><a href="/RBQ/nightly/guides/common/initial-pose.html">Initial Pose &amp; Power On</a></li></ul>',18)])])}const f=a(s,[["render",l]]);export{b as __pageData,f as default};
